import backtrader as bt


class BollingerBandwidthReversalStrategy(bt.Strategy):
    def __init__(self):
        self.bb = bt.indicators.BollingerBands(
            self.data.close, period=20, devfactor=2
        )
        self.bandwidth = (self.bb.top - self.bb.bot) / self.bb.mid
        self.bw_sma = bt.indicators.SMA(self.bandwidth, period=20)
        self.bw_std = bt.indicators.StdDev(self.bandwidth, period=20)
        self.bw_z = (self.bandwidth - self.bw_sma) / self.bw_std
        self.atr = bt.indicators.ATR(self.data, period=14)

        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if order is self.order:
                self.order = None
                if self.position:
                    stop_distance = 2 * self.atr[0]
                    if self.position.size > 0:
                        stop_price = order.executed.price - stop_distance
                        self.stop_order = self.sell(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
                    else:
                        stop_price = order.executed.price + stop_distance
                        self.stop_order = self.buy(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
            elif order is self.stop_order:
                self.stop_order = None
        elif order.status in (
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order is not None:
            return

        z_now = self.bw_z[0]
        z_prior = self.bw_z[-1]
        bandwidth_decreasing = self.bandwidth[0] < self.bandwidth[-1]
        bandwidth_increasing = self.bandwidth[0] > self.bandwidth[-1]

        if not self.position:
            if z_prior > 2 and z_now <= 2 and bandwidth_decreasing:
                self.order = self.buy()
            elif z_prior < -2 and z_now >= -2 and bandwidth_increasing:
                self.order = self.sell()
            return

        crosses_zero = (
            (z_prior < 0 and z_now >= 0)
            or (z_prior > 0 and z_now <= 0)
        )
        if crosses_zero or abs(z_now) < 0.5:
            if self.stop_order is not None:
                self.cancel(self.stop_order)
            self.order = self.close()
